	existing := make(map[id.CheckpointID]struct{})
	if rootTreeHash == plumbing.ZeroHash {
		return existing, nil
	}
	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, fmt.Errorf("failed to read /main root tree: %w", err)
