		sessions[sessionIndex] = filePaths
	}

	lastOpts := groupOpts[len(groupOpts)-1]
	if err := s.writeFreshMainBatchCheckpointSummary(lastOpts, basePath, entries, sessions, groupOpts); err != nil {
