	modeList   runMode = "list"
	modeDryRun runMode = "dry-run"
	modeApply  runMode = "apply"
)

type options struct {
	repoPath string
	since    string
	head     string
	mode     runMode
	help     bool
}

func main() {
	if err := run(context.Background(), os.Args[1:], os.Stdout); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
