+		return 0, nil
+	}
+
+	summary, err := m.v2Store.ReadCommitted(ctx, discovered.ID)
+	if err != nil {
+		return 0, fmt.Errorf("read v2 checkpoint %s: %w", discovered.ID, err)
+	}
+	if summary == nil || len(summary.Sessions) == 0 {
+		m.report.MissingV2Metadata++
+		return 0, nil
+	}
+
+	migratedSessions := 0
