	remoteAndBranch := strings.TrimPrefix(nameString, remotePrefix)
	_, branchName, ok := strings.Cut(remoteAndBranch, "/")
	if !ok {
		return false
	}
	return branchName == paths.MetadataBranchName || branchName == paths.TrailsBranchName
}

